begin;
alter table public.vendors add constraint vendor_coordinates check(public_lon between -180 and 180 and public_lat between -90 and 90);
alter table public.runners add constraint runner_coordinates check(public_lon between -180 and 180 and public_lat between -90 and 90);
create function public.create_vendor(display_name text,vendor_slug text,category_name text,longitude numeric,latitude numeric) returns uuid language plpgsql security definer set search_path='' as $$ declare id uuid;begin if not public.has_role('vendor') then raise exception 'Vendor role required';end if;if length(display_name) not between 1 and 150 or vendor_slug!~'^[a-z0-9-]{1,150}$' or category_name not in ('Food','Gifts','Makers','Farm','Shops','Services') then raise exception 'Invalid vendor';end if;insert into public.vendors(owner_id,name,slug,category,public_lon,public_lat,demo,verified) values(auth.uid(),display_name,vendor_slug,category_name,longitude,latitude,true,false) returning vendors.id into id;return id;end; $$;
create function public.create_listing(vendor_id uuid,listing_title text,listing_description text,category_name text,listing_mode text,price bigint,stock integer,local_made boolean) returns uuid language plpgsql security definer set search_path='' as $$ declare id uuid;begin if not public.owns_vendor(vendor_id) then raise exception 'Vendor owner required';end if;if length(listing_title) not between 1 and 150 or length(listing_description)>2000 or category_name not in ('Food','Gifts','Makers','Farm','Shops','Services') then raise exception 'Invalid listing';end if;insert into public.listings(vendor_id,title,description,category,mode,price_cents,inventory,made_local) values(vendor_id,listing_title,listing_description,category_name,listing_mode,price,stock,local_made) returning listings.id into id;return id;end; $$;
create function public.set_vendor_pickup(vendor_id uuid,address text,longitude numeric,latitude numeric) returns void language plpgsql security definer set search_path='' as $$ begin if not public.owns_vendor(vendor_id) or length(address) not between 5 and 500 or longitude not between -180 and 180 or latitude not between -90 and 90 then raise exception 'Invalid or unauthorized pickup';end if;insert into public.vendor_private values(vendor_id,address,longitude,latitude) on conflict(vendor_id) do update set pickup_address=excluded.pickup_address,pickup_lon=excluded.pickup_lon,pickup_lat=excluded.pickup_lat;insert into public.audit_events(actor_id,event,resource_id) values(auth.uid(),'VENDOR_PICKUP_CHANGED',vendor_id);end; $$;
create function public.assign_role(target_user uuid,wanted public.app_role,longitude numeric,latitude numeric) returns void language plpgsql security definer set search_path='' as $$ begin if not public.has_role('admin') then raise exception 'Admin required';end if;insert into public.user_roles(user_id,role) values(target_user,wanted) on conflict do nothing;if wanted='runner' then insert into public.runners(id,public_lon,public_lat) values(target_user,longitude,latitude) on conflict(id) do nothing;end if;end; $$;
revoke execute on function public.create_vendor(text,text,text,numeric,numeric),public.create_listing(uuid,text,text,text,text,bigint,integer,boolean),public.set_vendor_pickup(uuid,text,numeric,numeric),public.assign_role(uuid,public.app_role,numeric,numeric) from public,anon,authenticated;
grant execute on function public.create_vendor(text,text,text,numeric,numeric),public.create_listing(uuid,text,text,text,text,bigint,integer,boolean),public.set_vendor_pickup(uuid,text,numeric,numeric),public.assign_role(uuid,public.app_role,numeric,numeric) to authenticated;
commit;
